import * as T from './vendor/three.module.js';
export function installBuilders({scene,camera,colliders,pause,rewards,getCurrentSeat=()=>null}){
 const group=new T.Group();group.name='Making of Krownlandia garden';scene.add(group);
 const stone=new T.MeshStandardMaterial({color:'#e9ddc4'}),navy=new T.MeshStandardMaterial({color:'#163c61'}),gold=new T.MeshStandardMaterial({color:'#e9bd59',metalness:.65,roughness:.3}),green=new T.MeshStandardMaterial({color:'#386746'}),pink=new T.MeshStandardMaterial({color:'#e887b3'});
 const part=(geo,material,x,y,z)=>{const o=new T.Mesh(geo,material);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;group.add(o);return o;};
 const box=(x,y,z,w,h,d,m,solid=false)=>{const o=part(new T.BoxGeometry(w,h,d),m,x,y,z);if(solid)colliders.push({x,z,w:w/2+.35,d:d/2+.35});return o;};
 box(-26,.06,32,12,.12,12,stone);box(-16,.07,34,20,.14,3,stone);
 box(-26,.7,28,4,1.4,.8,navy,true);box(-26,1.5,28,4.4,.18,1,gold);
 const plaque=document.createElement('canvas');plaque.width=1024;plaque.height=512;const ctx=plaque.getContext('2d');ctx.fillStyle='#163c61';ctx.fillRect(0,0,1024,512);ctx.strokeStyle='#e9bd59';ctx.lineWidth=8;ctx.strokeRect(12,12,1000,488);ctx.textAlign='center';ctx.fillStyle='#f8e5af';ctx.font='bold 54px Georgia';ctx.fillText('MAKING OF KROWNLANDIA',512,96);ctx.font='34px Georgia';ctx.fillText('Imagination & Collaboration',512,167);ctx.font='29px sans-serif';ctx.fillText('Community origins · January 22, 2020',512,252);ctx.fillText('Named by @gorayii · Designer @lisachandler',512,308);ctx.fillText('3D prototype assisted by ChatGPT',512,394);
 const texture=new T.CanvasTexture(plaque);texture.colorSpace=T.SRGBColorSpace;part(new T.PlaneGeometry(5,2.5),new T.MeshStandardMaterial({map:texture}),-26,2.6,28.45);
 const crown=new T.Group();crown.name='Builders garden crown';crown.position.set(-26,4.25,28);group.add(crown);const ring=new T.Mesh(new T.TorusGeometry(.67,.1,8,24),gold);ring.rotation.x=Math.PI/2;crown.add(ring);for(let i=0;i<5;i++){const a=i*Math.PI*2/5,o=new T.Mesh(new T.ConeGeometry(.15,.8,6),gold);o.position.set(Math.sin(a)*.62,.3,Math.cos(a)*.62);crown.add(o);}
 for(const x of [-31,-21]){box(x,.26,29.5,1.5,.52,4,navy,true);box(x,.54,29.5,1.3,.07,3.8,green);for(let i=0;i<12;i++)part(new T.SphereGeometry(.16,7,5),i%2?pink:gold,x+Math.sin(i*2.4)*.43,.78,28+i*.27);}
 box(-26,.6,36,3.2,.2,.9,navy,true);box(-26,1.05,36.4,3.2,.85,.12,navy);for(const x of [-27.25,-24.75])box(x,.28,36,.14,.55,.65,gold);
 const seats=[{name:'Making of Krownlandia bench',x:-26,z:36,y:1.4,yaw:0,approach:{x:-26,z:34.7},kind:'builders'}];
 const near=()=>Math.hypot(camera.position.x+26,camera.position.z-30)<2.1;
 const canRead=()=>near()||seats.includes(getCurrentSeat());
 const souvenir={id:'builders-crown',name:'Builder’s Crown',color:'#d9ad4c'};
 const chapters=[
  ['Community beginnings','Krownlandia began on January 22, 2020 at 9:45 am Pacific in the KROWN DAC and Token Telegram community. Members imagined what they would like in an ideal town. The name was contributed by @gorayii, with Lisa Chandler (@lisachandler) credited as designer. Architects Day celebrates those beginnings.'],
  ['Places imagined together','Community members contributed buildings, homes, nature, events and activities, with individual place credits recorded in the original list. The established villages include Eldergrove, Meadowbrook, Riverbend, Stonehearth, Sunvale and Whispering Pines. Their traditions and community ideas will guide future additions here.'],
  ['The current 3D prototype','This theme-park prototype is a later chapter of Krownlandia, developed with Lisa Chandler and design and coding assistance from ChatGPT. Its crown-gate artwork is a concept for this prototype. The recent rides, rewards, seating and park housing build on the wider community world; the prototype’s Meadow, Bluewater and Woodland areas are recent additions. The current rendering remains stylized.',true]
 ];
 const dialog=document.createElement('dialog');dialog.id='buildersExhibit';dialog.setAttribute('aria-labelledby','buildersTitle');const title=document.createElement('h2');title.id='buildersTitle';title.textContent='Making of Krownlandia';const credit=document.createElement('p');credit.className='builders-credit';credit.textContent='Krownlandia was created through the ideas of its KROWN DAC and Token community. Named by @gorayii; designer Lisa Chandler (@lisachandler). This later 3D prototype includes design and development assistance from ChatGPT.';
 const tabs=document.createElement('div');tabs.id='buildersChapters';const body=document.createElement('section');body.id='buildersStory';const status=document.createElement('p');status.id='buildersStatus';status.setAttribute('role','status');const claim=document.createElement('button');claim.id='buildersClaim';claim.textContent='Collect Builder’s Crown';const close=document.createElement('button');close.id='buildersClose';close.textContent='Return to the garden';close.onclick=()=>dialog.close();dialog.append(title,credit,tabs,body,status,claim,close);document.body.append(dialog);const css=document.createElement('link');css.rel='stylesheet';css.href='builders.css';document.head.append(css);
 let page=0;const seen=()=>new Set([0,1,2].filter(i=>rewards.state().done.includes('builders-page-'+i))),buttons=[];const owned=()=>rewards.state().done.includes('builders-story');
 function render(){body.replaceChildren();const h=document.createElement('h3');h.textContent=chapters[page][0];const p=document.createElement('p');p.textContent=chapters[page][1];body.append(h,p);if(chapters[page][2]){const img=document.createElement('img');img.src='krownlandia-gateway-photoreal.png';img.alt='Recent theme-park prototype concept: a gold and sapphire crown gate, gardens and a distant palace.';const caption=document.createElement('p');caption.className='builders-caption';caption.textContent='Theme-park prototype concept art · Krownlandia’s community history predates this image.';body.append(img,caption);}buttons.forEach((b,i)=>{b.setAttribute('aria-pressed',String(i===page));b.textContent=(owned()||seen().has(i)?'✓ ':'')+(i+1)+'. '+chapters[i][0];});claim.disabled=owned()||seen().size<3;claim.textContent=owned()?'Builder’s Crown collected':'Collect Builder’s Crown';status.textContent=owned()?'Thank you for being part of Krownlandia. Your crown is in the keepsake journal and can be displayed at home. ':seen().size+' / 3 chapters explored · View all three to collect the Builder’s Crown.';if(owned())status.textContent+=rewards.state().claims.includes('builders:task')?'Your 20-point task reward is already collected.':'Your 20-point task reward is ready at the garden’s rewards station.';if(!rewards.state().saved)status.textContent+=' Progress lasts for this visit; browser storage is unavailable.';}
 chapters.forEach((chapter,i)=>{const b=document.createElement('button');b.id='buildersChapter-'+i;b.textContent=(i+1)+'. '+chapter[0];b.onclick=()=>{if(!canRead()||!dialog.open)return;page=i;rewards.recordBuildersPage(i);render();};buttons.push(b);tabs.append(b);});
 claim.onclick=()=>{if(!canRead()||!dialog.open||seen().size<3||owned())return;rewards.completeBuilders();render();};
 const reward=document.createElement('button');reward.id='buildersRewards';reward.textContent='Find garden rewards';reward.onclick=()=>{if(!canRead()||!dialog.open)return;pause();rewards.guideTo('builders');dialog.close();};dialog.append(reward);
 function open(){if(!canRead()||dialog.open)return false;pause();const unread=[0,1,2].find(i=>!seen().has(i));if(!owned()&&unread!==undefined)page=unread;rewards.recordBuildersPage(page);render();dialog.showModal();return true;}
 return {open,seats,collection:()=>owned()?[souvenir]:[],get near(){return near()},get isOpen(){return dialog.open}};
}
